// One category name in, on every click of a "Record: <category>" node.
// Keeps its own per-category counter in flow context, so recordings number
// 01, 02, 03... independently per category, picking up where a previous
// session left off (flow context here is only in-memory, so a Node-RED
// restart resets the counters back to whatever files already exist on
// disk not being auto-detected - see the README for how to resume past a
// restart without overwriting existing recordings).
const category = msg.payload;
const countKey = 'count_' + category;
const index = (flow.get(countKey) || 0) + 1;
flow.set(countKey, index);
flow.set('current', { category, index });

const trigger = { payload: 'R' };
const status = { payload: `recording ${category} #${String(index).padStart(2, '0')}...` };
return [trigger, status];

// The board streams one line per sample between two marker lines,
// REC_START and REC_END - see nano33-audio-capture.ino. This function
// buffers samples in flow context between those markers, and on REC_END
// builds the CSV text for the recording named in flow.current (set by the
// "start recording" function when this recording was triggered).
const text = String(msg.payload || '').trim();
if (text === '') return [null, null];

if (text === 'REC_START') {
    flow.set('buf', []);
    return [null, null];
}

if (text === 'REC_END') {
    const buf = flow.get('buf') || [];
    const current = flow.get('current');
    flow.set('buf', null);
    flow.set('current', null);

    if (!current) {
        node.warn(`REC_END with no pending recording, dropped ${buf.length} samples`);
        return [null, null];
    }

    let csv = 'sample_index,amplitude\n';
    for (let i = 0; i < buf.length; i++) {
        csv += i + ',' + buf[i] + '\n';
    }

    const index = String(current.index).padStart(2, '0');
    const filename = `../data/${current.category}/${current.category}_${index}.csv`;
    return [{ payload: csv, filename, samples: buf.length }, null];
}

const buf = flow.get('buf');
if (buf) {
    const n = Number(text);
    if (!Number.isNaN(n)) buf.push(n);
    return [null, null];
}

// Not between REC_START/REC_END and not one of the two markers - the
// board's own boot banner ({"status":"ready",...}) or an init error.
return [null, msg];
